    private void calculateActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_calculateActionPerformed
    try {
        // 1. Clear previous text from the large breakdown output area
        output.setText(""); 
        
        // 2. Read values from your text fields using your variable names
        double loanAmt = Double.parseDouble(loanAmount.getText());
        int totalMonths = Integer.parseInt(loanDuration.getText());

        // 3. Run validation checks using pop-up dialog boxes
        if (loanAmt <= 0) {
            javax.swing.JOptionPane.showMessageDialog(this, "ERROR: Loan Amount must be greater than zero.", "Input Error", javax.swing.JOptionPane.ERROR_MESSAGE);
            return; 
        }
        
        if (totalMonths <= 0) {
            javax.swing.JOptionPane.showMessageDialog(this, "ERROR: Loan Duration must be greater than zero.", "Input Error", javax.swing.JOptionPane.ERROR_MESSAGE);
            return;
        }

        // 4. Run your exact math calculations
        double monthlyRate = 1.5;
        double currentBalance = loanAmt;
        double MonthlyRepayment = loanAmt / totalMonths;
        double rateFraction = monthlyRate / 100.0;

        double totalMonthlyRepayment = 0;
        double totalInterestPaid = 0;
        double totalOverallPaid = 0;

        // Construct the tabular header for your 'output' box
        StringBuilder breakdown = new StringBuilder();
        breakdown.append("LOAN BREAKDOWN\n");
        breakdown.append("------------------------------------------------------------------------------------------------------\n");
        breakdown.append(String.format("%-10s | %-20s | %-20s | %-20s\n", "Month", "Monthly Payment", "Monthly Interest", "Monthly Repayment"));
        breakdown.append("------------------------------------------------------------------------------------------------------\n");

        for (int month = 1; month <= totalMonths; month++) {
            double interestAmount = currentBalance * rateFraction;
            double totalMonthlyPayment = MonthlyRepayment + interestAmount;

            totalMonthlyRepayment += MonthlyRepayment;
            totalInterestPaid += interestAmount;
            totalOverallPaid += totalMonthlyPayment;

            breakdown.append(String.format("%-10d | NGN%-18.2f | NGN%-18.2f | NGN%-18.2f\n",
                    month, MonthlyRepayment, interestAmount, totalMonthlyPayment));

            currentBalance -= MonthlyRepayment;
        }

        // 5. Send results to your respective output components
        output.setText(breakdown.toString());
        totalInterest.setText(String.format("NGN%,.2f", totalInterestPaid));
        loanRepayment.setText(String.format("NGN%,.2f", totalOverallPaid));

    } catch (NumberFormatException e) {
        javax.swing.JOptionPane.showMessageDialog(this, "ERROR! ENTER THE APPROPRIATE VALUE", "Input Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }
    }//GEN-LAST:event_calculateActionPerformed

